// Kaval watcher: classify YOLO labels into watch-post events + gimbal target
const THREAT={elephant:'elephant',bear:'bear',person:'person',truck:'vehicle',car:'vehicle',bus:'vehicle',motorcycle:'vehicle',cow:'cattle',dog:'dog',horse:'animal',sheep:'animal',bird:'bird'};
const PRIORITY=['elephant','bear','person','vehicle','cattle','animal','dog','bird'];
const QUIET_FROM=Number(env.get('KV_QUIET_FROM')||18), QUIET_TO=Number(env.get('KV_QUIET_TO')||6); // person = intrusion only at night
const data=msg.payload?.data||{};
const labels=Array.isArray(data.labels)?data.labels.map(String):[];
const boxes=Array.isArray(data.boxes)?data.boxes:[];
const res=Array.isArray(data.resolution)?data.resolution:[640,640];
flow.set('kvLastLabels',labels);
if(data.image) flow.set('kvImage',data.image);
const st=flow.get('kv')||{history:[],alertUntil:0,pan:90,tilt:90,tracking:false};
let best=null;
for(let i=0;i<labels.length;i++){
  const t=THREAT[labels[i].toLowerCase()]; if(!t) continue;
  if(!best||PRIORITY.indexOf(t)<PRIORITY.indexOf(best.type)){
    const b=boxes[i]||[]; // [x,y,w,h,score,cls]
    let sc=Number(b[4]??0.8); if(sc>1) sc=sc/100; best={type:t,confidence:sc,box:b};
  }
}
const h=Math.floor(((Date.now()/3600000)+Number(env.get('KV_TZ_OFFSET')||5.5))%24); // local (IST) hour
const night=(h>=QUIET_FROM||h<QUIET_TO);
let threat=false;
if(best){
  if(best.type==='person') threat=night||env.get('KV_PERSON_ALWAYS')==='1';
  else threat=['elephant','bear','vehicle'].includes(best.type);
  // gimbal: aim at box centre (box x,y are centre px in model resolution)
  if(best.box.length>=4){
    const cx=best.box[0]/res[0], cy=best.box[1]/res[1];
    st.pan=Math.round(180-cx*180); st.tilt=Math.round(60+cy*60);
  }
  st.tracking=true; st.lastSeen=Date.now();
  const last=st.history[0];
  const sameRecent=last&&last.type===best.type&&(Date.now()-new Date(last.time).getTime())<20000;
  if(!sameRecent){
    const det={type:best.type,confidence:Math.round(best.confidence*100)/100,time:new Date().toISOString(),source:'camera',snapshot:data.image?'/api/snapshot.jpg':null};
    st.history.unshift(det); if(st.history.length>50) st.history.pop();
    st.last=det;
    if(data.image) flow.set('kvSnap',data.image);
  }
  if(threat) st.alertUntil=Date.now()+Number(env.get('KV_HOLD_MS')||15000);
}else{
  if(Date.now()-(st.lastSeen||0)>5000){ st.tracking=false; st.pan=90; st.tilt=90; }
}
flow.set('kv',st);
node.status({fill:threat?'red':best?'yellow':'green',shape:'dot',text:best?best.type:'clear'});
if(threat){ msg.payload='on'; return msg; }
return null;

const pin=String(env.get('GPIO_PIN')||'490').trim();
const level=msg.payload==='on'?1:0;
const g=`/sys/class/gpio/gpio${pin}`;
msg.payload=`[ -d ${g} ] || printf ${pin} > /sys/class/gpio/export; printf out > ${g}/direction; printf ${level} > ${g}/value;`;
return msg;

// payload = raw WAV buffer from arecord (2 s, 16 kHz mono S16_LE). Compute RMS level.
if(!Buffer.isBuffer(msg.payload)||msg.payload.length<1000) return null;
const b=msg.payload; let sum=0,n=0;
for(let i=44;i+1<b.length;i+=2){ const v=b.readInt16LE(i); sum+=v*v; n++; }
const rms=Math.sqrt(sum/Math.max(n,1))/32768;
const level=Math.round(rms*1000)/10;            // 0..100
const TH=Number(env.get('KV_AUDIO_THRESH')||12);  // tune on site
const au=flow.get('kvAudio')||{streak:0};
au.level=level; au.loud=level>TH; au.streak=au.loud?(au.streak||0)+1:0;
flow.set('kvAudio',au);
node.status({fill:au.loud?'red':'green',shape:'ring',text:`audio ${level}`});
if(au.streak===3){ // ~6 s of sustained loud machine noise
  const st=flow.get('kv')||{history:[],alertUntil:0,pan:90,tilt:90};
  const det={type:'chainsaw',confidence:Math.min(0.99,Math.round((level/100+0.5)*100)/100),time:new Date().toISOString(),source:'audio',snapshot:flow.get('kvImage')?'/api/snapshot.jpg':null};
  st.history.unshift(det); if(st.history.length>50) st.history.pop();
  st.last=det; st.alertUntil=Date.now()+Number(env.get('KV_HOLD_MS')||15000);
  if(flow.get('kvImage')) flow.set('kvSnap',flow.get('kvImage'));
  flow.set('kv',st);
  msg.payload='on'; return msg;
}
return null;

msg.headers={'Content-Type':'application/json','Cache-Control':'no-store','Access-Control-Allow-Origin':'*'};
const st=flow.get('kv')||{history:[],alertUntil:0,pan:90,tilt:90,tracking:false};
const au=flow.get('kvAudio')||{};
const alert=Date.now()<(st.alertUntil||0);
let battery=Number(env.get('KV_BATTERY')||100);
msg.payload={
  id:env.get('KV_ID')||'KDN-01',
  name:env.get('KV_NAME')||'Vadakkumbhagam Post',
  battery, alert,
  issue: battery<15?'Low battery':'',
  pan:st.pan, tilt:st.tilt, tracking:!!st.tracking,
  last_detection: st.last||null,
  history: st.history||[],
  audio:{level:au.level||0, loud:!!au.loud},
  labels: flow.get('kvLastLabels')||[],
  uptime_s: Math.round((Date.now()-(flow.get('kvStart')||(flow.set('kvStart',Date.now()),Date.now())))/1000)
};
return msg;

const img=flow.get('kvSnap')||flow.get('kvImage');
if(!img){ msg.statusCode=404; msg.payload='no snapshot yet'; return msg; }
msg.headers={'Content-Type':'image/jpeg','Cache-Control':'no-store'};
msg.payload=Buffer.from(String(img).replace(/^data:image\/\w+;base64,/,''),'base64');
return msg;

msg.headers={'Content-Type':'text/plain','Cache-Control':'no-store'};
const st=flow.get('kv')||{pan:90,tilt:90};
msg.payload=`${st.pan},${st.tilt}`;   // ESP32 servo bridge polls this
return msg;
